{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache

PRICE = 800
# Price in cents of a group of n different books.
GROUP_PRICE = {
    0: 0,
    1: PRICE,
    2: 2 * PRICE * 95 // 100,
    3: 3 * PRICE * 90 // 100,
    4: 4 * PRICE * 80 // 100,
    5: 5 * PRICE * 75 // 100,
}


@lru_cache(maxsize=None)
def _best(counts):
    if not counts:
        return 0
    best = None
    for size in range(1, len(counts) + 1):
        rest = [c - 1 for c in counts[:size]] + list(counts[size:])
        rest = tuple(sorted((c for c in rest if c > 0), reverse=True))
        cost = GROUP_PRICE[size] + _best(rest)
        if best is None or cost < best:
            best = cost
    return best


def total(basket):
    """Return the lowest price in cents for the basket."""
    counts = tuple(sorted(Counter(basket).values(), reverse=True))
    return _best(counts)
